package com.powerlevelling.client.hud;

import com.mojang.blaze3d.systems.RenderSystem;
import com.powerlevelling.PowerLevelling;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;

/*
 * HUD ATLAS LAYOUT  --  assets/powerlevelling/textures/gui/hud.png  (256 x 256, transparent)
 * Generated by tools/make_hud_textures.py; keep both files in sync.   Format: NAME  u, v, w, h
 *
 *   y=0   FRAME     (  0,  0, 8, 8)  9-slice panel frame, corner = 3 (outline + bevel; navy body ~92% alpha)
 *         INSET     (  8,  0, 6, 6)  9-slice sunken row background, corner = 2
 *         ACCENT    ( 16,  0, 4, 1)  orange #F28C28 accent line (stretch horizontally)
 *         ACCENT_HI ( 20,  0, 4, 1)  light orange highlight line
 *
 *   y=16  TRACK     (  0, 16, 6, 6)  9-slice empty bar track, corner = 2 (1px dark border + inner shadow)
 *         SEG       (  8, 16, 1, 5)  segment divider (1px dark gap, drawn over the bar interior)
 *         TICK      ( 10, 16, 3, 7)  I-beam marker (Ki Break threshold at 25%)
 *         HATCH     ( 16, 16, 8, 5)  diagonal hatching tile (max stamina lost to endurance), tile it
 *
 *   y=32  Bar fills, each 4 x 6: row 0 = 1px highlight, rows 1..5 = vertical gradient. Stretch horizontally.
 *         FILL_HP        (  0, 32, 4, 6)  red   #D93A3A -> #9E1F1F
 *         FILL_KI        (  4, 32, 4, 6)  cyan  #4FC3FF -> #1E78C8
 *         FILL_KI_BREAK  (  8, 32, 4, 6)  red-orange #FF6A2A -> #B8280F
 *         FILL_STAMINA   ( 12, 32, 4, 6)  yellow-green #E8D44A -> #8FB52E
 *         FILL_EXP       ( 16, 32, 4, 6)  gold  #FFD84A -> #C98F10
 *         GHOST_HP       ( 20, 32, 4, 6)  pale pink  (damage trail)
 *         GHOST_KI       ( 24, 32, 4, 6)  pale cyan  (ki trail)
 *         GHOST_STAMINA  ( 28, 32, 4, 6)  pale yellow-green
 *         WHITE          ( 30, 32, 2, 2)  solid white, tinted with RenderSystem.setShaderColor for pulse overlays
 *
 *   y=48  Icons
 *         ICON_HEART  (  0, 48,  9,  9)
 *         ICON_FLAME  ( 10, 48,  9,  9)  original stylized ki flame
 *         ICON_BOLT   ( 20, 48,  9,  9)  stamina lightning bolt
 *         ICON_STAR   ( 32, 48, 15, 15)  level badge background (15x15 so two digits fit inside; the only non-9x9 icon)
 *
 *   y=64  Stats-screen icons (9 x 9)
 *         ICON_SWORD  (  0, 64,  9,  9)  Strength
 *         ICON_SHIELD ( 10, 64,  9,  9)  Defense
 *         ICON_SPARK  ( 20, 64,  9,  9)  Ki Power
 *
 * Everything else in the atlas is transparent (free space for later sprites).
 */

/** Atlas constants plus the shared drawing helpers used by the HUD layer, PixelUi and the screens. */
public final class HudSprites {
    public static final ResourceLocation ATLAS =
            ResourceLocation.fromNamespaceAndPath(PowerLevelling.MODID, "textures/gui/hud.png");
    public static final int ATLAS_W = 256;
    public static final int ATLAS_H = 256;

    /** A rectangle in the atlas. */
    public record Sprite(int u, int v, int w, int h) {
    }

    // Panels / lines
    public static final Sprite FRAME = new Sprite(0, 0, 8, 8);
    public static final int FRAME_CORNER = 3;
    public static final Sprite INSET = new Sprite(8, 0, 6, 6);
    public static final int INSET_CORNER = 2;
    public static final Sprite ACCENT = new Sprite(16, 0, 4, 1);
    public static final Sprite ACCENT_HI = new Sprite(20, 0, 4, 1);

    // Bars
    public static final Sprite TRACK = new Sprite(0, 16, 6, 6);
    public static final int TRACK_CORNER = 2;
    public static final Sprite SEG = new Sprite(8, 16, 1, 5);
    public static final Sprite TICK = new Sprite(10, 16, 3, 7);
    public static final Sprite HATCH = new Sprite(16, 16, 8, 5);

    // Fills (4x6: highlight row + 5 gradient rows)
    public static final Sprite FILL_HP = new Sprite(0, 32, 4, 6);
    public static final Sprite FILL_KI = new Sprite(4, 32, 4, 6);
    public static final Sprite FILL_KI_BREAK = new Sprite(8, 32, 4, 6);
    public static final Sprite FILL_STAMINA = new Sprite(12, 32, 4, 6);
    public static final Sprite FILL_EXP = new Sprite(16, 32, 4, 6);
    public static final Sprite GHOST_HP = new Sprite(20, 32, 4, 6);
    public static final Sprite GHOST_KI = new Sprite(24, 32, 4, 6);
    public static final Sprite GHOST_STAMINA = new Sprite(28, 32, 4, 6);
    public static final Sprite WHITE = new Sprite(30, 32, 2, 2);

    // Icons
    public static final Sprite ICON_HEART = new Sprite(0, 48, 9, 9);
    public static final Sprite ICON_FLAME = new Sprite(10, 48, 9, 9);
    public static final Sprite ICON_BOLT = new Sprite(20, 48, 9, 9);
    public static final Sprite ICON_STAR = new Sprite(32, 48, 15, 15);
    public static final Sprite ICON_SWORD = new Sprite(0, 64, 9, 9);
    public static final Sprite ICON_SHIELD = new Sprite(10, 64, 9, 9);
    public static final Sprite ICON_SPARK = new Sprite(20, 64, 9, 9);

    private HudSprites() {
    }

    // ---- primitives -----------------------------------------------------------------------------------------------

    /** Draws a sprite 1:1. */
    public static void sprite(GuiGraphics g, Sprite s, int x, int y) {
        RenderSystem.enableBlend();
        g.blit(ATLAS, x, y, (float) s.u(), (float) s.v(), s.w(), s.h(), ATLAS_W, ATLAS_H);
    }

    /** Draws the atlas region (u, v, uw, vh) stretched to w x h. */
    public static void stretch(GuiGraphics g, int x, int y, int w, int h, int u, int v, int uw, int vh) {
        if (w <= 0 || h <= 0) return;
        RenderSystem.enableBlend();
        g.blit(ATLAS, x, y, w, h, (float) u, (float) v, uw, vh, ATLAS_W, ATLAS_H);
    }

    /** Draws a whole sprite stretched to w x h. */
    public static void stretch(GuiGraphics g, Sprite s, int x, int y, int w, int h) {
        stretch(g, x, y, w, h, s.u(), s.v(), s.w(), s.h());
    }

    /** Generic 9-slice: corners drawn 1:1, edges and centre stretched. Needs w,h >= 2*corner. */
    public static void nineSlice(GuiGraphics g, Sprite s, int corner, int x, int y, int w, int h) {
        int c = corner;
        int mw = s.w() - 2 * c;
        int mh = s.h() - 2 * c;
        int u = s.u();
        int v = s.v();
        int iw = w - 2 * c;
        int ih = h - 2 * c;
        // corners
        stretch(g, x, y, c, c, u, v, c, c);
        stretch(g, x + w - c, y, c, c, u + s.w() - c, v, c, c);
        stretch(g, x, y + h - c, c, c, u, v + s.h() - c, c, c);
        stretch(g, x + w - c, y + h - c, c, c, u + s.w() - c, v + s.h() - c, c, c);
        // edges
        stretch(g, x + c, y, iw, c, u + c, v, mw, c);
        stretch(g, x + c, y + h - c, iw, c, u + c, v + s.h() - c, mw, c);
        stretch(g, x, y + c, c, ih, u, v + c, c, mh);
        stretch(g, x + w - c, y + c, c, ih, u + s.w() - c, v + c, c, mh);
        // centre
        stretch(g, x + c, y + c, iw, ih, u + c, v + c, mw, mh);
    }

    // ---- panels ---------------------------------------------------------------------------------------------------

    /** Window frame (outline, bevel, navy body). */
    public static void frame(GuiGraphics g, int x, int y, int w, int h) {
        nineSlice(g, FRAME, FRAME_CORNER, x, y, w, h);
    }

    /** Frame plus the thin orange accent line just inside the top edge. */
    public static void frameWithAccent(GuiGraphics g, int x, int y, int w, int h) {
        frame(g, x, y, w, h);
        stretch(g, ACCENT, x + 3, y + 3, w - 6, 1);
    }

    /** Sunken row background. */
    public static void inset(GuiGraphics g, int x, int y, int w, int h) {
        nineSlice(g, INSET, INSET_CORNER, x, y, w, h);
    }

    /** 2px divider line: light orange over orange. */
    public static void accentLine(GuiGraphics g, int x, int y, int w) {
        stretch(g, ACCENT_HI, x, y, w, 1);
        stretch(g, ACCENT, x, y + 1, w, 1);
    }

    // ---- bars -----------------------------------------------------------------------------------------------------

    /** Empty track; the interior is (x+1, y+1, w-2, h-2). Needs w >= 4, h >= 4. */
    public static void track(GuiGraphics g, int x, int y, int w, int h) {
        nineSlice(g, TRACK, TRACK_CORNER, x, y, w, h);
    }

    /** Draws a fill sprite over the horizontal span [from, to) (interior pixels) of a track at (x, y, w, h). */
    public static void fillRange(GuiGraphics g, Sprite fill, int x, int y, int w, int h, int from, int to) {
        int span = to - from;
        int ih = h - 2;
        if (span <= 0 || ih <= 0) return;
        int fx = x + 1 + from;
        int fy = y + 1;
        stretch(g, fx, fy, span, 1, fill.u(), fill.v(), fill.w(), 1);                // highlight row
        if (ih > 1) stretch(g, fx, fy + 1, span, ih - 1, fill.u(), fill.v() + 1, fill.w(), fill.h() - 1); // gradient
    }

    /** Translucent tinted rectangle (pulse / flash overlays). Drawn with a blit so it keeps program order with other blits. */
    public static void flash(GuiGraphics g, int x, int y, int w, int h, float r, float gr, float b, float a) {
        if (w <= 0 || h <= 0 || a <= 0f) return;
        RenderSystem.setShaderColor(r, gr, b, Mth.clamp(a, 0f, 1f));
        stretch(g, x, y, w, h, WHITE.u(), WHITE.v(), WHITE.w(), WHITE.h());
        RenderSystem.setShaderColor(1f, 1f, 1f, 1f);
    }

    /** Dark thin strip (e.g. the 2px EXP bar) without a border: track colour then fill, all sprites. */
    public static void thinBar(GuiGraphics g, Sprite fill, int x, int y, int w, int h, float fraction) {
        stretch(g, x, y, w, h, TRACK.u() + 2, TRACK.v() + 2, 1, 1); // interior colour of the track sprite
        int px = (int) (w * Mth.clamp(fraction, 0f, 1f));
        if (px <= 0) return;
        stretch(g, x, y, px, 1, fill.u(), fill.v(), fill.w(), 1);
        if (h > 1) stretch(g, x, y + 1, px, h - 1, fill.u(), fill.v() + 1, fill.w(), fill.h() - 1);
    }

    /** Interior pixel width for a fraction (floored, so a non-empty value always shows at least 1px if > 0). */
    public static int pixels(int w, float fraction) {
        float f = Mth.clamp(fraction, 0f, 1f);
        int iw = w - 2;
        int px = (int) (iw * f);
        return (f > 0f && px == 0) ? 1 : px;
    }

    /** Simple track + fill bar (used by the screens): fraction 0..1. */
    public static void bar(GuiGraphics g, int x, int y, int w, int h, float fraction, Sprite fill) {
        track(g, x, y, w, h);
        fillRange(g, fill, x, y, w, h, 0, pixels(w, fraction));
    }

    /** Segment dividers (count-1 one-pixel gaps) across a track's interior. */
    public static void segments(GuiGraphics g, int x, int y, int w, int h, int count) {
        int iw = w - 2;
        int ih = h - 2;
        for (int i = 1; i < count; i++) {
            int sx = x + 1 + Math.round(iw * i / (float) count);
            stretch(g, sx, y + 1, 1, ih, SEG.u(), SEG.v(), 1, SEG.h());
        }
    }

    /** Hatched overlay over interior span [from, to), tiled so the stripes stay continuous. */
    public static void hatch(GuiGraphics g, int x, int y, int w, int h, int from, int to) {
        int ih = h - 2;
        int tileW = HATCH.w();
        int px = from;
        while (px < to) {
            int phase = px % tileW;                 // keep stripes aligned to the bar, not to the span start
            int run = Math.min(tileW - phase, to - px);
            stretch(g, x + 1 + px, y + 1, run, ih, HATCH.u() + phase, HATCH.v(), run, HATCH.h());
            px += run;
        }
    }

    /** Vertical tick marker centred on interior column cx, spanning the whole track height. */
    public static void tick(GuiGraphics g, int x, int y, int w, int h, int interiorCx) {
        int ty = y + (h - TICK.h()) / 2;
        sprite(g, TICK, x + 1 + interiorCx - 1, ty);
    }

}
